#!/bin/bash
set -euo pipefail

# telegram-node-example - Generated by flowsh
# Registry-based workflow execution script

echo "Starting workflow: telegram-node-example"

# Workflow variables and state management
declare -A workflow_vars
declare -A workflow_state

# Color codes for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
NC='\033[0m'

# Configuration
VERBOSE=${VERBOSE:-false}
AGENT_TIMEOUT=${AGENT_TIMEOUT:-60}

# =============================================================================
# VARIABLE MANAGEMENT FUNCTIONS
# =============================================================================

# Set variable with debug logging
# Usage: set_var "variable_name" "value" "node_id"
set_var() {
    local var_name="$1"
    local value="$2" 
    local node_id="${3:-root}"
    
    # Set the variable globally
    declare -g "$var_name"="$value"
    
    # Debug logging when FLOWSH_DEBUG=true
    if [[ "${FLOWSH_DEBUG:-false}" == "true" ]]; then
        echo "[DEBUG] $node_id: SET $var_name = '$value'" >&2
    fi
}

# Get variable value with debug logging  
# Usage: get_var "variable_name" "node_id"
get_var() {
    local var_name="$1"
    local node_id="${2:-root}"
    
    # Get the variable value using indirect expansion
    local value="${!var_name:-}"
    
    # Debug logging when FLOWSH_DEBUG=true
    if [[ "${FLOWSH_DEBUG:-false}" == "true" ]]; then
        echo "[DEBUG] $node_id: GET $var_name = '$value'" >&2
    fi
    
    # Return the value
    echo "$value"
}

# Environment Variables
WORKFLOW_NAME=${WORKFLOW_NAME:-""}
NOTIFICATION_LEVEL=${NOTIFICATION_LEVEL:-""}
TEST_CHAT_ID=${TEST_CHAT_ID:-""}
USER_NAME=${USER_NAME:-""}
TELEGRAM_SUCCESS=${TELEGRAM_SUCCESS:-""}
TELEGRAM_HTTP_CODE=${TELEGRAM_HTTP_CODE:-""}
TELEGRAM_RESPONSE=${TELEGRAM_RESPONSE:-""}
TELEGRAM_MESSAGE_SENT=${TELEGRAM_MESSAGE_SENT:-""}
TELEGRAM_ERROR=${TELEGRAM_ERROR:-""}
ERROR_MESSAGE=${ERROR_MESSAGE:-""}
TELEGRAM_SUMMARY=${TELEGRAM_SUMMARY:-""}

# =============================================================================
# UTILITY FUNCTIONS
# =============================================================================

# Logging functions with colors
log_info() {
    echo -e "${CYAN}ℹ️  $*${NC}"
}

log_success() {
    echo -e "${GREEN}✅ $*${NC}"
}

log_error() {
    echo -e "${RED}❌ $*${NC}" >&2
}

log_warning() {
    echo -e "${YELLOW}⚠️  $*${NC}" >&2
}

log_debug() {
    [[ "$VERBOSE" == "true" ]] && echo -e "${BLUE}🔍 DEBUG: $*${NC}" >&2 || true
}

log_step() {
    echo -e "${CYAN}🚀 $*${NC}"
}

# Operation logging with correlation IDs
log_operation_start() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    log_debug "$correlation_id" "Starting $operation_type: $operation_name"
}

log_operation_end() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    local status="${4:-success}"
    log_debug "$correlation_id" "Completed $operation_type: $operation_name ($status)"
}

# Enhanced error handling
handle_error() {
    local exit_code=$1
    local context="$2"
    local node_id="${3:-unknown}"
    
    case $exit_code in
        124)
            log_error "Timeout: $context took longer than ${AGENT_TIMEOUT}s (node: $node_id)"
            ;;
        127)
            log_error "Command not found in: $context (node: $node_id)"
            ;;
        1)
            log_error "General error in: $context (node: $node_id)"
            ;;
        *)
            log_error "Unknown error (exit code $exit_code) in: $context (node: $node_id)"
            ;;
    esac
    
    return $exit_code
}

# Variable management
set_workflow_var() {
    local var_name="$1"
    local var_value="$2"
    workflow_vars["$var_name"]="$var_value"
    log_debug "Set variable: $var_name = $var_value"
}

get_workflow_var() {
    local var_name="$1"
    local default_value="${2:-}"
    echo "${workflow_vars[$var_name]:-$default_value}"
}

# State management
set_workflow_state() {
    local state_key="$1"
    local state_value="$2"
    workflow_state["$state_key"]="$state_value"
    log_debug "Set state: $state_key = $state_value"
}

get_workflow_state() {
    local state_key="$1"
    local default_value="${2:-}"
    echo "${workflow_state[$state_key]:-$default_value}"
}

# Variable substitution in templates
substitute_variables() {
    local template="$1"
    local result="$template"
    
    # Find all variable references in the format {{#variable_name#}}
    while [[ $result =~ \{\{#([^#]+)#\}\} ]]; do
        local var_ref="${BASH_REMATCH[1]}"
        local var_value=$(get_workflow_var "$var_ref" "")
        
        if [[ -z "$var_value" ]]; then
            log_warning "Variable reference '$var_ref' not found, using empty string"
        fi
        
        # Escape special characters for sed
        local escaped_value=$(printf '%s\n' "$var_value" | sed 's/[[\.\*^\$()+?{|]/\\&/g')
        result=$(echo "$result" | sed "s|{{#${var_ref}#}}|$escaped_value|g")
    done
    
    echo "$result"
}

# Workflow Execution

# Node: simple_message

# Node: simple_message (Simple HTML Message)
send_telegram_simple_message() {
    log_step "📱 Sending Telegram message: Simple HTML Message"

    local message="🚀 <b>Workflow Started!</b>

<i>Workflow Name:</i> <code>$(get_var "WORKFLOW_NAME" "simple_message")</code>
<i>User:</i> <code>$(get_var "USER_NAME" "simple_message")</code>
<i>Notification Level:</i> <code>$(get_var "NOTIFICATION_LEVEL" "simple_message")</code>

<b>Status:</b> ✅ Initialization Complete
"
    local parse_mode="HTML"
    local max_retries=3
    local disable_notification=false
    local error_handling="continue"
    

    # Validate message is not empty
    if [[ -z "$message" ]]; then
        log_error "Telegram message content is empty"
        case "$error_handling" in
            "ignore")
                log_info "Ignoring Telegram error as configured"
                return 0
                ;;
            "continue")
                log_warning "Continuing despite Telegram error"
                return 0
                ;;
            *)
                return 1
                ;;
        esac
    fi

    # Use chat_id from environment variable
    local chat_id="${TELEGRAM_CHAT_ID:-}"
    
    if [[ -z "$chat_id" ]]; then
        log_error "Telegram chat_id is required - set TELEGRAM_CHAT_ID environment variable or provide chat_id in node configuration"
        case "continue" in
            "ignore")
                log_info "Ignoring Telegram configuration error as configured"
                return 0
                ;;
            "continue")
                log_warning "Continuing despite Telegram configuration error"
                return 0
                ;;
            *)
                return 1
                ;;
        esac
    fi

    # Use bot_token from environment variable
    local bot_token="${TELEGRAM_BOT_TOKEN:-}"
    
    if [[ -z "$bot_token" ]]; then
        log_error "Telegram bot token is required - set TELEGRAM_BOT_TOKEN environment variable or provide bot_token in node configuration"
        case "continue" in
            "ignore")
                log_info "Ignoring Telegram configuration error as configured"
                return 0
                ;;
            "continue")
                log_warning "Continuing despite Telegram configuration error"
                return 0
                ;;
            *)
                return 1
                ;;
        esac
    fi

    # Character escaping functions for Telegram
    escape_json() {
        local text="$1"
        # Escape characters that would break JSON payload
        text="${text//\\/\\\\}"  # Escape backslashes first
        text="${text//"/\\"}"      # Escape double quotes
        text="${text//$'\n'/\\n}"  # Escape newlines
        text="${text//$'\r'/\\r}"  # Escape carriage returns
        text="${text//$'\t'/\\t}"  # Escape tabs
        echo "$text"
    }

    escape_markdown() {
        local text="$1"
        # Escape special MarkdownV2 characters
        text="${text//_/\_}"
        text="${text//*/\*}"
        text="${text//[/\[}"
        text="${text//]/\]}"
        text="${text//(/\(}"
        text="${text//)/\)}"
        text="${text//~/\~}"
        text="${text//\`/\\\`}"
        text="${text//>/\>}"
        text="${text//#/\#}"
        text="${text//+/\+}"
        text="${text//-/\-}"
        text="${text//=/\=}"
        text="${text//|/\|}"
        text="${text//\{/\\{}"
        text="${text//\}/\\}}"
        text="${text//./\.}"
        text="${text//!/\!}"
        echo "$text"
     }

    # Escape message content for JSON payload (but preserve formatting tags)
    local escaped_message
    case "$parse_mode" in
        "HTML")
            # For HTML mode, only escape JSON special characters, not HTML formatting tags
            escaped_message=$(escape_json "$message")
            ;;
        "Markdown"|"MarkdownV2")
            escaped_message=$(escape_markdown "$message")
            ;;
        *)
            escaped_message=$(escape_json "$message")
            ;;
    esac

    # Prepare API request payload
    local api_url="https://api.telegram.org/bot$bot_token/sendMessage"
    local payload
    payload=$(cat <<EOF
{
    "chat_id": "$chat_id",
    "text": "$escaped_message",
    "parse_mode": "$parse_mode",
    "disable_notification": true
}
EOF
)

    log_debug "Sending message to Telegram API: $api_url"
    log_debug "Payload length: ${#payload} characters"

    # Retry logic with exponential backoff
    local attempt=1
    local delay=1
    
    while [[ $attempt -le $max_retries ]]; do
        log_debug "Telegram API attempt $attempt of $max_retries"
        
        # Make API request
        local response_file=$(mktemp)
        local http_code
        
        http_code=$(curl -s -w "%{http_code}" \
            -X POST \
            -H "Content-Type: application/json" \
            -d "$payload" \
            --connect-timeout 10 \
            --max-time 30 \
            "$api_url" \
            -o "$response_file" 2>/dev/null)
        
        local curl_exit_code=$?
        local response_body=$(cat "$response_file" 2>/dev/null)
        
        # Clean up temp file
        rm -f "$response_file" 2>/dev/null
        
        # Check if request was successful
        if [[ $curl_exit_code -eq 0 && "$http_code" =~ ^2[0-9][0-9]$ ]]; then
            log_success "Telegram message sent successfully (HTTP $http_code)"
            
            # Set success variables
            set_workflow_var "telegram_success" "true"
            set_workflow_var "telegram_http_code" "$http_code"
            set_workflow_var "telegram_response" "$response_body"
            set_workflow_var "telegram_message_sent" "true"
            
            log_debug "Telegram API response: $response_body"
            return 0
        else
            # Log the failure
            if [[ $curl_exit_code -ne 0 ]]; then
                log_warning "Telegram API request failed (curl exit code: $curl_exit_code) - attempt $attempt/$max_retries"
            else
                log_warning "Telegram API returned HTTP $http_code - attempt $attempt/$max_retries"
                if [[ -n "$response_body" ]]; then
                    log_warning "API error response: $response_body"
                fi
            fi
            
            # Check if we should retry
            if [[ $attempt -lt $max_retries ]]; then
                log_info "Retrying in ${delay}s..."
                sleep $delay
                delay=$((delay * 2))  # Exponential backoff
                attempt=$((attempt + 1))
            else
                # Final failure - handle based on error_handling setting
                log_error "Telegram message failed after $max_retries attempts"
                
                # Set failure variables
                set_workflow_var "telegram_success" "false"
                set_workflow_var "telegram_http_code" "${http_code:-0}"
                set_workflow_var "telegram_response" "$response_body"
                set_workflow_var "telegram_message_sent" "false"
                set_workflow_var "telegram_error" "MAX_RETRIES_EXCEEDED"
                
                case "$error_handling" in
                    "ignore")
                        log_info "Ignoring Telegram failure as configured"
                        return 0
                        ;;
                    "continue")
                        log_warning "Continuing despite Telegram failure"
                        return 0
                        ;;
                    *)
                        return 1
                        ;;
                esac
            fi
        fi
    done
}
send_telegram_simple_message

